const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig");
fn go(rig: *rigz.Rig, mode: task.Mode, name: []const u8, args: task.Args) !u32 { var cx = rig.ctx(mode); return jrun.run(&cx, jobs.find(name).?, args); }
fn must(rig: *rigz.Rig, prefix: []const u8) !void { if (!rig.waitPre(prefix, 4000)) { std.debug.print("missing record: {s}\n", .{prefix}); return error.TestUnexpectedResult; } }
fn lots(rig: *rigz.Rig) void { rig.conf.capz_acct_dayz = 99; rig.conf.capz_prod_dayz = 99; rig.conf.capz_data_dayz = 99; rig.conf.capz_mone_dayz = 99; rig.conf.capz_acce_dayz = 99; rig.conf.capz_sett_dayz = 99; rig.conf.capz_help_dayz = 99; rig.conf.tena_name_main = "acme"; }
test "catalog: unique names, first step is goto, steps carry what they need" { for (jobs.JOBS, 0..) |jb, ix| { for (jobs.JOBS[ix + 1 ..]) |oth| try std.testing.expect(!std.mem.eql(u8, jb.name, oth.name)); try std.testing.expect(jb.steps.len >= 1); try std.testing.expect(jb.steps[0].op == .goto); try std.testing.expect(jb.hint.len > 0); } try std.testing.expect(jobs.JOBS.len >= 60); }
test "catalog: irreversible and costly jobs are risky, reads and small writes are not" { const risky = [_][]const u8{ "signup-setup", "region-subscribe", "tenancy-close", "pass-change", "mfa-off", "key-revoke", "user-invite", "user-drop", "policy-create", "policy-drop", "payg-upgrade", "payment-open", "bill-pay", "budget-drop", "inst-create", "inst-stop", "inst-reboot", "inst-drop", "vcn-drop", "rule-add", "vol-create", "vol-drop", "bucket-drop", "adb-stop" }; for (risky) |nam| try std.testing.expect(jobs.find(nam).?.risk == .x); const safe = [_][]const u8{ "usage-view", "plan-view", "limits-view", "login", "signup", "key-create", "inst-list", "inst-start", "budget-create", "vcn-create", "bucket-create", "metrics-view" }; for (safe) |nam| try std.testing.expect(jobs.find(nam).?.risk == .w); const once = [_][]const u8{ "signup", "signup-setup", "tenancy-close", "region-subscribe", "payg-upgrade" }; for (once) |nam| try std.testing.expect(jobs.find(nam).?.once); try std.testing.expect(jobs.find("login").?.auth and !jobs.find("key-create").?.auth); }
test "dry-run shows the plan and changes nothing for every job" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); const args: task.Args = .{ .text = "t", .to = "a@b.co", .url = "/limits", .title = "T", .price = "5", .desc = "d", .group = "g", .photo = "p.jpg", .opt = "o" }; for (jobs.JOBS) |jb| { try std.testing.expectEqual(@as(u32, 1), try go(&rig, .dry, jb.name, args)); } try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expect(std.mem.find(u8, rig.sink.items, "dry-run: preview only") != null); }
test "args are checked and secrets are required for live login" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); try std.testing.expectError(error.BadUsage, go(&rig, .live, "verify-email", .{})); try std.testing.expectError(error.BadUsage, go(&rig, .live, "inst-create", .{ .title = "x" })); var cx = rig.ctx(.live); cx.secr_user = ""; cx.secr_pass = ""; try std.testing.expectError(error.NoSecret, jrun.run(&cx, jobs.find("login").?, .{})); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "account: signup once-only, verify link, login with tenancy, logout, reset, sso, mfa" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); try std.testing.expectEqual(@as(u32, 1), try go(&rig, .live, "signup", .{ .title = "Kim", .desc = "Doe", .opt = "Vietnam" })); try must(&rig, "btn|Verify my email|tester@example.com|Kim|Doe"); try must(&rig, "opt|Country=Vietnam"); try std.testing.expectEqual(@as(u32, 0), try go(&rig, .live, "signup", .{ .title = "Kim", .desc = "Doe", .opt = "Vietnam" })); try std.testing.expect(std.mem.find(u8, rig.sink.items, "already done earlier") != null); const link = try std.fmt.allocPrint(rig.aren.allocator(), "{s}/signup/setup", .{rig.base()}); _ = try go(&rig, .live, "verify-email", .{ .url = link }); _ = try go(&rig, .live, "login", .{}); try must(&rig, "btn|Next|acme"); try must(&rig, "btn|Sign In|acme|tester@example.com|pw-secret-1"); _ = try go(&rig, .live, "logout", .{}); try must(&rig, "btn|Sign out"); _ = try go(&rig, .live, "reset-pass", .{}); try must(&rig, "btn|Send reset link||tester@example.com|"); _ = try go(&rig, .live, "sso-start", .{}); try must(&rig, "btn|Single Sign-On"); _ = try go(&rig, .live, "mfa-on", .{}); try must(&rig, "tog|Multi-factor authentication=on"); }
test "account: risky changes need force, setup picks the home region" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "signup-setup", .{ .opt = "US East (Ashburn)" })); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "tenancy-close", .{})); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "region-subscribe", .{ .opt = "US East (Ashburn)" })); _ = try go(&rig, .force, "signup-setup", .{ .opt = "US East (Ashburn)" }); try must(&rig, "opt|Home region=US East (Ashburn)"); try must(&rig, "btn|Create account|pw-secret-1|pw-secret-1|acme"); _ = try go(&rig, .force, "region-subscribe", .{ .opt = "US East (Ashburn)" }); try must(&rig, "btn|Subscribe"); _ = try go(&rig, .force, "pass-change", .{ .opt = "newpw-1" }); try must(&rig, "btn|Change password|pw-secret-1|newpw-1"); _ = try go(&rig, .force, "mfa-off", .{}); _ = try go(&rig, .force, "tenancy-close", .{}); try must(&rig, "btn|Confirm termination"); _ = try go(&rig, .live, "profile-view", .{}); _ = try go(&rig, .live, "tenancy-view", .{}); }
test "access: api keys, users, policies, compartments" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "key-create", .{ .text = "KEYBODY" }); try must(&rig, "btn|Add|KEYBODY"); _ = try go(&rig, .live, "key-list", .{}); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "key-revoke", .{})); _ = try go(&rig, .force, "key-revoke", .{}); try must(&rig, "btn|Delete key"); _ = try go(&rig, .live, "user-list", .{}); _ = try go(&rig, .force, "user-invite", .{ .to = "bob@example.com", .opt = "Readers" }); try must(&rig, "opt|Groups=Readers"); try must(&rig, "btn|Send invite|bob@example.com"); _ = try go(&rig, .force, "user-drop", .{ .to = "ann@example.com" }); try must(&rig, "btn|Delete user"); _ = try go(&rig, .live, "group-list", .{}); _ = try go(&rig, .live, "policy-list", .{}); _ = try go(&rig, .force, "policy-create", .{ .title = "pol-one", .text = "Allow group A to read all-resources in tenancy" }); try must(&rig, "btn|Create|pol-one|Allow group A to read all-resources in tenancy"); _ = try go(&rig, .force, "policy-drop", .{ .title = "ci-policy" }); try must(&rig, "btn|Delete policy"); _ = try go(&rig, .live, "comp-list", .{}); _ = try go(&rig, .live, "comp-create", .{ .title = "ci-comp" }); try must(&rig, "btn|Create|ci-comp"); }
test "money and settings: credits, invoices, upgrade, budgets with alert" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "plan-view", .{}); _ = try go(&rig, .live, "invoice-list", .{}); _ = try go(&rig, .live, "invoice-get", .{}); try must(&rig, "btn|Download invoice"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "payg-upgrade", .{})); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "bill-pay", .{})); _ = try go(&rig, .force, "payg-upgrade", .{}); try must(&rig, "btn|Confirm upgrade"); _ = try go(&rig, .force, "payment-open", .{}); try must(&rig, "btn|Add payment method"); _ = try go(&rig, .force, "bill-pay", .{}); try must(&rig, "btn|Confirm payment"); _ = try go(&rig, .live, "budget-list", .{}); _ = try go(&rig, .live, "budget-create", .{ .title = "free-guard", .price = "1" }); try must(&rig, "btn|Create|free-guard|1|"); _ = try go(&rig, .live, "budget-alert", .{ .title = "ci-budget", .price = "80", .to = "ops@example.com" }); try must(&rig, "btn|Save alert|||80|ops@example.com"); _ = try go(&rig, .force, "budget-drop", .{ .title = "ci-budget" }); try must(&rig, "btn|Delete budget"); _ = try go(&rig, .live, "prefs-view", .{}); _ = try go(&rig, .live, "secu-view", .{}); }
test "compute: list, view, create needs force, start, stop, reboot, terminate" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "inst-list", .{}); _ = try go(&rig, .live, "inst-view", .{ .title = "ci-box" }); const mk: task.Args = .{ .title = "ci-new", .opt = "VM.Standard.A1.Flex", .text = "ssh-ed25519 AAAA" }; try std.testing.expectError(error.NeedApprove, go(&rig, .live, "inst-create", mk)); _ = try go(&rig, .force, "inst-create", mk); try must(&rig, "btn|Select shape"); try must(&rig, "btn|Create|ci-new|ssh-ed25519 AAAA"); _ = try go(&rig, .live, "inst-start", .{ .title = "ci-box" }); try must(&rig, "btn|Start instance"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "inst-stop", .{ .title = "ci-box" })); _ = try go(&rig, .force, "inst-stop", .{ .title = "ci-box" }); try must(&rig, "btn|Confirm stop"); _ = try go(&rig, .force, "inst-reboot", .{ .title = "ci-box" }); try must(&rig, "btn|Confirm reboot"); _ = try go(&rig, .force, "inst-drop", .{ .title = "ci-box" }); try must(&rig, "btn|Terminate instance"); _ = try go(&rig, .live, "metrics-view", .{ .title = "ci-box" }); try must(&rig, "btn|Monitoring"); }
test "network and storage: vcn, open port needs force, ip, volume, bucket, upload, database, shell" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "vcn-list", .{}); _ = try go(&rig, .live, "vcn-create", .{ .title = "ci-vcn2" }); try must(&rig, "btn|Create|ci-vcn2"); _ = try go(&rig, .live, "secl-view", .{ .title = "ci-vcn" }); try must(&rig, "btn|Security Lists"); try std.testing.expectError(error.NeedApprove, go(&rig, .live, "rule-add", .{ .title = "ci-vcn", .text = "10.0.0.0/16", .opt = "22" })); _ = try go(&rig, .force, "rule-add", .{ .title = "ci-vcn", .text = "10.0.0.0/16", .opt = "22" }); try must(&rig, "btn|Save rule||10.0.0.0/16|22"); _ = try go(&rig, .force, "vcn-drop", .{ .title = "ci-vcn" }); try must(&rig, "btn|Terminate VCN"); _ = try go(&rig, .live, "ip-reserve", .{ .title = "ci-ip" }); try must(&rig, "btn|Reserve|ci-ip"); _ = try go(&rig, .live, "vol-list", .{}); _ = try go(&rig, .force, "vol-create", .{ .title = "ci-vol2", .price = "50" }); try must(&rig, "btn|Create|ci-vol2|50"); _ = try go(&rig, .force, "vol-drop", .{ .title = "ci-vol" }); try must(&rig, "btn|Terminate volume"); _ = try go(&rig, .live, "bucket-list", .{}); _ = try go(&rig, .live, "bucket-create", .{ .title = "ci-bucket2" }); try must(&rig, "btn|Create|ci-bucket2"); _ = try go(&rig, .live, "obj-list", .{ .title = "ci-bucket" }); const pth = try rig.absOf("up.txt"); try std.Io.Dir.cwd().writeFile(rig.iozz, .{ .sub_path = try std.fmt.allocPrint(rig.aren.allocator(), ".zig-cache/tmp/{s}/up.txt", .{rig.tmpz.sub_path}), .data = "hello\n" }); _ = try go(&rig, .live, "obj-upload", .{ .title = "ci-bucket", .photo = pth }); try must(&rig, "file|1"); try must(&rig, "btn|Confirm upload"); _ = try go(&rig, .force, "bucket-drop", .{ .title = "ci-bucket" }); try must(&rig, "btn|Delete bucket"); _ = try go(&rig, .live, "adb-list", .{}); _ = try go(&rig, .live, "adb-start", .{ .title = "ci-db" }); try must(&rig, "btn|Start database"); _ = try go(&rig, .force, "adb-stop", .{ .title = "ci-db" }); try must(&rig, "btn|Confirm stop"); _ = try go(&rig, .live, "shell-open", .{}); try must(&rig, "btn|Developer tools"); }
test "data and help: cost, limits, audit, export, docs, support, feedback, any page" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); lots(&rig); _ = try go(&rig, .live, "usage-view", .{}); _ = try go(&rig, .live, "limits-view", .{}); _ = try go(&rig, .live, "limits-find", .{ .text = "A1" }); try must(&rig, "key|Search limits=A1"); _ = try go(&rig, .live, "audit-view", .{}); _ = try go(&rig, .live, "report-export", .{}); try must(&rig, "btn|Export"); _ = try go(&rig, .live, "docs-open", .{}); _ = try go(&rig, .live, "docs-search", .{ .text = "always free" }); try must(&rig, "key|Search=always free"); _ = try go(&rig, .live, "support-send", .{ .title = "Hello", .text = "Need help" }); try must(&rig, "btn|Send|Hello|Need help"); _ = try go(&rig, .live, "feedback-send", .{ .text = "Great" }); try must(&rig, "btn|Send|Great"); _ = try go(&rig, .live, "page-open", .{ .url = "/limits" }); }
test "caps apply per kind and a failed run keeps the key free" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_acct_dayz = 1; rig.conf.tena_name_main = "acme"; _ = try go(&rig, .live, "login", .{}); try std.testing.expectError(error.CapHit, go(&rig, .live, "login", .{})); rig.conf.retr_coun_maxz = 1; var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const cfgz = @import("cf-conf-load.zig"); const ovr = try cfgz.confParse(aren.allocator(), "{\"labl_over\":{\"supp_send\":[\"zzz no such\"]}}"); rig.conf.labl_over = ovr.labl_over; try std.testing.expectError(error.NoElement, go(&rig, .live, "feedback-send", .{ .text = "x" })); }
